@SpringBootTest
@Testcontainers
class OrderRepositoryIT {

    @Container
    @ServiceConnection
    static PostgreSQLContainer postgres = new PostgreSQLContainer("postgres:16-alpine");

    @Autowired OrderRepository repository;

    @Test
    void findsPaidOrders() {
        repository.save(new Order(OrderStatus.PAID));
        assertThat(repository.findByStatus(OrderStatus.PAID)).hasSize(1);
    }
}

